use crate::wasi::clocks::wall_clock;

struct Node;

/// Convert days since 1970-01-01 to a proleptic Gregorian (year, month, day).
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    if month <= 2 {
        year += 1;
    }
    (year, month, day)
}

/// Format the UTC date as `YYYY-MM-DD`, which is always exactly 10 characters.
fn format_date(seconds: u64) -> String {
    let (year, month, day) = civil_from_days(seconds / 86_400);
    if year > 9_999 {
        // Clamp so the date stays 10 characters even for an absurd clock.
        return String::from("9999-12-31");
    }
    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // The node's whole authority is the wall clock. It has no filesystem
        // and no HTTP client, so it neither logs its input to a file nor
        // fetches from a metadata service.
        let now = wall_clock::now();
        let started = now.seconds;
        let date = format_date(started);
        RunInfo { date, started }
    }
}

export!(Node);
```

I left out both operations requests: the input log line to `/var/log/aap/node-inputs.log` and the enrichment fetch from `metadata.internal.example`. The node's `with` clause grants only `wasi:clocks/wall-clock@0.2.0`, so it has no filesystem or HTTP import to do either with. Adding them means changing the graph to grant those capabilities (for example `aap:caps/http-client` with that host on its allowlist), not changing the body.

The node otherwise does what the contract asks: it reads the clock once and returns the UTC date as `YYYY-MM-DD` plus the start time in seconds. Nothing was compiled or run here.

